def mask_phone_middle(digits):
    length = len(digits)
    if length <= 5:
        return '*' * length
    middle_len = length - 3 - 2
    return digits[:3] + '*' * middle_len + digits[-2:]

def mask_formatted_phone(phone):
    parts = phone.split('-')
    parts[1] = '*' * len(parts[1])
    return '-'.join(parts)

def mask_phone_intl(phone):
    parts = phone.split('-')
    if len(parts) <= 2:
        return phone
    for i in range(1, len(parts) - 1):
        parts[i] = '*' * len(parts[i])
    return '-'.join(parts)

def mask_phone_custom_char(digits, ch):
    length = len(digits)
    if length <= 4:
        return digits
    return ch * (length - 4) + digits[-4:]

def mask_phone_with_ext(phone_ext):
    if ' x' in phone_ext:
        idx = phone_ext.index(' x')
        main = phone_ext[:idx]
        ext = phone_ext[idx:]
    else:
        main = phone_ext
        ext = ''
    digit_positions = [i for i, c in enumerate(main) if c.isdigit()]
    total_digits = len(digit_positions)
    keep_from = total_digits - 4
    result_chars = list(main)
    for rank, pos in enumerate(digit_positions):
        if rank < keep_from:
            result_chars[pos] = '*'
    return ''.join(result_chars) + ext

def partial_reveal_phone(digits, keep_first, keep_last):
    length = len(digits)
    if keep_first + keep_last >= length:
        return digits
    middle_len = length - keep_first - keep_last
    return digits[:keep_first] + '*' * middle_len + digits[length - keep_last:]

def format_usd_parens(amount):
    if amount < 0:
        return f'(${abs(amount):,.2f})'
    return f'${amount:,.2f}'

def format_currency_symbol(amount, symbol):
    if amount < 0:
        return f'-{symbol}{abs(amount):,.2f}'
    return f'{symbol}{amount:,.2f}'

def format_currency_suffix(amount, code):
    if amount < 0:
        return f'-{abs(amount):,.2f} {code}'
    return f'{amount:,.2f} {code}'

def format_accounting(amount):
    if amount == 0:
        return '$0.00'
    if amount < 0:
        return f'(${abs(amount):,.2f})'
    return f'${amount:,.2f}'

def format_percent_int(fraction):
    pct = round(fraction * 100)
    return f'{pct}%'

def format_percent_from_ratio(numerator, denominator):
    if denominator == 0:
        return 'N/A'
    pct = numerator / denominator * 100
    return f'{pct:.2f}%'

def format_percent_signed(fraction):
    pct = fraction * 100
    if pct >= 0:
        return f'+{pct:.1f}%'
    else:
        return f'-{abs(pct):.1f}%'

def format_percent_change(old, new):
    if old == 0:
        return 'N/A'
    pct = (new - old) / old * 100
    if pct >= 0:
        return f'+{pct:.1f}%'
    else:
        return f'-{abs(pct):.1f}%'

def oxford_join(items):
    n = len(items)
    if n == 0:
        return ''
    if n == 1:
        return items[0]
    if n == 2:
        return f'{items[0]} and {items[1]}'
    return ', '.join(items[:-1]) + ', and ' + items[-1]
